DROP POLICY IF EXISTS "Users can view active offices" ON offices_agenda_inteligente_orus; DROP POLICY IF EXISTS "Authenticated users can insert offices" ON offices_agenda_inteligente_orus; DROP POLICY IF EXISTS "Users can update offices they created" ON offices_agenda_inteligente_orus; DROP POLICY IF EXISTS "Users can delete offices they created" ON offices_agenda_inteligente_orus; CREATE POLICY "Users can view active offices" ON offices_agenda_inteligente_orus FOR SELECT USING (ativo = true); CREATE POLICY "Authenticated users can manage offices" ON offices_agenda_inteligente_orus FOR ALL USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);;
